using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using QuickRun.Core.Config;

namespace QuickRun.Core.Detect;

/// <summary>
/// One way a repository could be started. Nothing is executed to produce these - the commands are
/// text the user sees and picks from.
/// </summary>
public sealed record Candidate(
    string Kind,
    string Label,
    string RelativeDir,
    IReadOnlyList<string> Setup,
    IReadOnlyList<string> Run,
    int Confidence);

public static class Detector
{
    private const int MaxDepth = 3;

    private static readonly HashSet<string> SkipDirs = new(StringComparer.OrdinalIgnoreCase)
    {
        ".git", "node_modules", "bin", "obj", "dist", "build", ".venv", "venv",
        "target", "vendor", ".vs", ".idea", "__pycache__", ".next", ".nuxt",
    };

    private static readonly string[] ComposeNames =
        { "docker-compose.yml", "docker-compose.yaml", "compose.yml", "compose.yaml" };

    public static IReadOnlyList<Candidate> Detect(string root, OSKind os)
    {
        if (!Directory.Exists(root)) return Array.Empty<Candidate>();

        var candidates = new List<Candidate>();

        if (ConfigParser.FindRootScript(root, os) is { } script)
            candidates.Add(ScriptCandidate(root, script, os));

        foreach (var dir in Walk(root))
        {
            var relative = Relative(root, dir);
            candidates.AddRange(new[]
            {
                Compose(dir, relative),
                Node(dir, relative),
                Python(dir, relative, os),
                Make(dir, relative),
                Simple(dir, relative, "Cargo.toml", "cargo", "cargo run", 60),
                Simple(dir, relative, "go.mod", "go", "go run ./...", 60),
                Simple(dir, relative, "pom.xml", "maven", "mvn spring-boot:run", 55),
                Gradle(dir, relative),
            }.Where(c => c is not null).Select(c => c!));

            candidates.AddRange(DotNet(dir, relative));
        }

        return candidates
            .OrderByDescending(c => c.Confidence)
            .ThenBy(c => c.RelativeDir, StringComparer.OrdinalIgnoreCase)
            .ToList();
    }

    /// <summary>Renders a candidate as the config a human would have written for it.</summary>
    public static string ToYaml(Candidate candidate, string? name)
    {
        var builder = new StringBuilder();
        builder.AppendLine("# yaml-language-server: $schema=https://fgilde.github.io/QuickRun/quickrun.schema.json");
        builder.AppendLine($"# generated by quickrun from a detected {candidate.Kind} entry point - review before committing");
        builder.AppendLine("version: 1");
        if (!string.IsNullOrWhiteSpace(name)) builder.AppendLine($"name: {Quote(name!)}");

        var cwd = candidate.RelativeDir;

        if (candidate.Setup.Count > 0)
        {
            builder.AppendLine("setup:");
            foreach (var step in candidate.Setup)
            {
                builder.AppendLine($"  - run: {Quote(step)}");
                if (cwd.Length > 0) builder.AppendLine($"    cwd: {Quote(cwd)}");
            }
        }

        builder.AppendLine("tasks:");
        for (var i = 0; i < candidate.Run.Count; i++)
        {
            builder.AppendLine($"  - name: {(candidate.Run.Count == 1 ? "run" : $"task-{i + 1}")}");
            builder.AppendLine($"    run: {Quote(candidate.Run[i])}");
            if (cwd.Length > 0) builder.AppendLine($"    cwd: {Quote(cwd)}");
        }

        return builder.ToString();
    }

    // ---- signals ------------------------------------------------------------

    private static Candidate ScriptCandidate(string root, string script, OSKind os)
    {
        var name = Path.GetFileName(script);
        var command = os == OSKind.Windows && name.EndsWith(".ps1", StringComparison.OrdinalIgnoreCase)
            ? $"powershell -ExecutionPolicy Bypass -File ./{name}"
            : $"./{name}";
        return new("script", $"{name} in the repository root", "", Array.Empty<string>(), new[] { command }, 95);
    }

    private static Candidate? Compose(string dir, string relative) =>
        ComposeNames.Any(n => File.Exists(Path.Combine(dir, n)))
            ? new("compose", Label("docker compose up", relative), relative,
                Array.Empty<string>(), new[] { "docker compose up" }, 90)
            : null;

    private static Candidate? Node(string dir, string relative)
    {
        var packageJson = Path.Combine(dir, "package.json");
        if (!File.Exists(packageJson)) return null;

        string? script;
        try
        {
            using var document = JsonDocument.Parse(File.ReadAllText(packageJson));
            if (!document.RootElement.TryGetProperty("scripts", out var scripts)) return null;
            script = new[] { "dev", "start" }.FirstOrDefault(s => scripts.TryGetProperty(s, out _));
        }
        catch (JsonException)
        {
            return null;
        }
        catch (IOException)
        {
            return null;
        }

        if (script is null) return null;

        var (manager, install) = PackageManager(dir);
        return new("npm", Label($"{manager} run {script}", relative), relative,
            new[] { $"{manager} {install}" }, new[] { $"{manager} run {script}" }, 80);
    }

    private static (string Manager, string Install) PackageManager(string dir)
    {
        if (File.Exists(Path.Combine(dir, "pnpm-lock.yaml"))) return ("pnpm", "install");
        if (File.Exists(Path.Combine(dir, "yarn.lock"))) return ("yarn", "install");
        if (File.Exists(Path.Combine(dir, "bun.lockb"))) return ("bun", "install");
        return ("npm", File.Exists(Path.Combine(dir, "package-lock.json")) ? "ci" : "install");
    }

    private static IEnumerable<Candidate> DotNet(string dir, string relative)
    {
        foreach (var project in SafeFiles(dir, "*.csproj"))
        {
            string text;
            try { text = File.ReadAllText(project); } catch (IOException) { continue; }

            var name = Path.GetFileName(project);
            var projectPath = relative.Length == 0 ? name : $"{relative}/{name}";
            var command = $"dotnet run --project {projectPath}";

            var isAspire = text.Contains("Aspire.AppHost.Sdk", StringComparison.OrdinalIgnoreCase)
                           || text.Contains("<IsAspireHost>true", StringComparison.OrdinalIgnoreCase);
            if (isAspire)
            {
                yield return new("aspire", Label(command, relative), "", Array.Empty<string>(), new[] { command }, 85);
                continue;
            }

            var isRunnable = text.Contains("Microsoft.NET.Sdk.Web", StringComparison.OrdinalIgnoreCase)
                             || text.Contains("<OutputType>Exe", StringComparison.OrdinalIgnoreCase);
            if (isRunnable)
                yield return new("dotnet", Label(command, relative), "", Array.Empty<string>(), new[] { command }, 70);
        }
    }

    private static Candidate? Python(string dir, string relative, OSKind os)
    {
        var entry = new[] { "main.py", "app.py", "manage.py" }
            .FirstOrDefault(f => File.Exists(Path.Combine(dir, f)));
        if (entry is null) return null;

        var hasRequirements = File.Exists(Path.Combine(dir, "requirements.txt"));
        var hasPyProject = File.Exists(Path.Combine(dir, "pyproject.toml"));
        if (!hasRequirements && !hasPyProject) return null;

        if (!hasRequirements)
        {
            var usesUv = File.Exists(Path.Combine(dir, "uv.lock"));
            return usesUv
                ? new("python", Label($"uv run {entry}", relative), relative,
                    new[] { "uv sync" }, new[] { $"uv run {entry}" }, 75)
                : new("python", Label($"poetry run python {entry}", relative), relative,
                    new[] { "poetry install" }, new[] { $"poetry run python {entry}" }, 75);
        }

        var windows = os == OSKind.Windows;
        var create = windows ? "python -m venv .venv" : "python3 -m venv .venv";
        var pip = windows ? @".venv\Scripts\pip" : ".venv/bin/pip";
        var python = windows ? @".venv\Scripts\python" : ".venv/bin/python";

        return new("python", Label($"{python} {entry}", relative), relative,
            new[] { create, $"{pip} install -r requirements.txt" }, new[] { $"{python} {entry}" }, 75);
    }

    private static Candidate? Make(string dir, string relative)
    {
        var makefile = Path.Combine(dir, "Makefile");
        if (!File.Exists(makefile)) return null;

        string text;
        try { text = File.ReadAllText(makefile); } catch (IOException) { return null; }

        var target = new[] { "run", "dev" }.FirstOrDefault(t => TargetPattern(t).IsMatch(text));
        return target is null
            ? null
            : new("make", Label($"make {target}", relative), relative,
                Array.Empty<string>(), new[] { $"make {target}" }, 65);
    }

    private static Candidate? Gradle(string dir, string relative) =>
        File.Exists(Path.Combine(dir, "build.gradle")) || File.Exists(Path.Combine(dir, "build.gradle.kts"))
            ? new("gradle", Label("./gradlew bootRun", relative), relative,
                Array.Empty<string>(), new[] { "./gradlew bootRun" }, 55)
            : null;

    private static Candidate? Simple(string dir, string relative, string marker, string kind, string command, int confidence) =>
        File.Exists(Path.Combine(dir, marker))
            ? new(kind, Label(command, relative), relative, Array.Empty<string>(), new[] { command }, confidence)
            : null;

    // ---- helpers ------------------------------------------------------------

    private static IEnumerable<string> Walk(string root)
    {
        var queue = new Queue<(string Dir, int Depth)>();
        queue.Enqueue((root, 0));

        while (queue.Count > 0)
        {
            var (dir, depth) = queue.Dequeue();
            yield return dir;
            if (depth >= MaxDepth) continue;

            IEnumerable<string> children;
            try { children = Directory.EnumerateDirectories(dir); }
            catch (IOException) { continue; }
            catch (UnauthorizedAccessException) { continue; }

            foreach (var child in children)
                if (!SkipDirs.Contains(Path.GetFileName(child)))
                    queue.Enqueue((child, depth + 1));
        }
    }

    private static IEnumerable<string> SafeFiles(string dir, string pattern)
    {
        try { return Directory.EnumerateFiles(dir, pattern); }
        catch (IOException) { return Array.Empty<string>(); }
        catch (UnauthorizedAccessException) { return Array.Empty<string>(); }
    }

    private static string Relative(string root, string dir)
    {
        var relative = Path.GetRelativePath(root, dir).Replace('\\', '/');
        return relative == "." ? "" : relative;
    }

    private static string Label(string command, string relative) =>
        relative.Length == 0 ? command : $"{command} ({relative}/)";

    private static string Quote(string value) =>
        value.Length == 0 || value.AsSpan().IndexOfAny(":#{}[],&*!|>%@\"'") >= 0
        || value.StartsWith('-') || value.Trim() != value
            ? "\"" + value.Replace("\\", "\\\\").Replace("\"", "\\\"") + "\""
            : value;

    private static Regex TargetPattern(string target) =>
        new($@"^{Regex.Escape(target)}\s*:", RegexOptions.Multiline);
}
